import{_ as i,W as l,s as d,u,ah as o,I as p,w as a,Z as e,A as n}from"./chunks/framework.Dx7wo2et.js";import"./chunks/theme.CjgFg8Ql.js";const k=JSON.parse('{"title":"你使用过 Python 3.6 中针对文件系统的这个神奇方法吗？ | LCTT x X-CMD","titleTemplate":false,"description":"你使用过 Python 3.6 中针对文件系统的这个神奇方法吗？ | LCTT (202106) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"你使用过 Python 3.6 中针对文件系统的这个神奇方法吗？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"你使用过 Python 3.6 中针对文件系统的这个神奇方法吗？ | LCTT (202106) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202106/20210518 Are you using this magic method for filesystems from Python 3.6","title":"你使用过 Python 3.6 中针对文件系统的这个神奇方法吗？","tag":"202106"},"relativePath":"202106/20210518 Are you using this magic method for filesystems from Python 3.6.md","filePath":"[post].md"}'),h={name:"202106/20210518 Are you using this magic method for filesystems from Python 3.6.md"};function r(c,s,m,g,f,b){const t=l("Link");return u(),d("div",null,[s[24]||(s[24]=o(`<h1 id="你使用过-python-3-6-中针对文件系统的这个神奇方法吗" tabindex="-1">你使用过 Python 3.6 中针对文件系统的这个神奇方法吗？ <a class="header-anchor" href="#你使用过-python-3-6-中针对文件系统的这个神奇方法吗" aria-label="Permalink to 你使用过 Python 3.6 中针对文件系统的这个神奇方法吗？">​</a></h1><blockquote><p>探索 os.fspath 和其他两个未被充分利用但仍然有用的 Python 特性。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202106/03/164403a6m2c989hh963lm6.jpg" alt=""></p><p>这是 Python 3.x 首发特性系列文章中的第七篇。Python 3.6 首次发布于 2016 年，尽管它已经发布了一段时间，但它引入的许多特性都没有得到充分利用，而且相当酷。下面是其中的三个。</p><h3 id="分隔数字常数" tabindex="-1">分隔数字常数 <a class="header-anchor" href="#分隔数字常数" aria-label="Permalink to 分隔数字常数">​</a></h3><p>快回答哪个更大，<code>10000000</code> 还是 <code>200000</code>？你在看代码时能正确回答吗？根据当地的习惯，在写作中，你会用 10,000,000 或 10.000.000 来表示第一个数字。问题是，Python 使用逗号和句号是用于其他地方。</p><p>幸运的是，从 Python 3.6 开始，你可以使用下划线来分隔数字。这在代码中和使用字符串的 <code>int()</code> 转换器时都可以使用：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import math</span></span>
<span class="line"><span>math.log(10_000_000) / math.log(10)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    7.0</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>math.log(int(&quot;10_000_000&quot;)) / math.log(10)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    7.0</span></span></code></pre></div><h3 id="tau-是对的" tabindex="-1">Tau 是对的 <a class="header-anchor" href="#tau-是对的" aria-label="Permalink to Tau 是对的">​</a></h3>`,12)),p("p",null,[s[1]||(s[1]=a("45 度角用弧度表示是多少？一个正确的答案是 ")),s[2]||(s[2]=p("code",null,"π/4",-1)),s[3]||(s[3]=a("，但这有点难记。记住 45 度角是一个八分之一的转角要容易得多。正如 ")),e(t,{href:"https://tauday.com/tau-manifesto"},{default:n(()=>s[0]||(s[0]=[a("Tau Manifesto")])),_:1}),s[4]||(s[4]=a(" 所解释的，")),s[5]||(s[5]=p("code",null,"2π",-1)),s[6]||(s[6]=a("，称为 ")),s[7]||(s[7]=p("code",null,"Τ",-1)),s[8]||(s[8]=a("，是一个更自然的常数。"))]),s[25]||(s[25]=o(`<p>在 Python 3.6 及以后的版本中，你的数学代码可以使用更直观的常数：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>print(&quot;Tan of an eighth turn should be 1, got&quot;, round(math.tan(math.tau/8), 2))</span></span>
<span class="line"><span>print(&quot;Cos of an sixth turn should be 1/2, got&quot;, round(math.cos(math.tau/6), 2))</span></span>
<span class="line"><span>print(&quot;Sin of a quarter turn should be 1, go&quot;, round(math.sin(math.tau/4), 2))</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    Tan of an eighth turn should be 1, got 1.0</span></span>
<span class="line"><span>    Cos of an sixth turn should be 1/2, got 0.5</span></span>
<span class="line"><span>    Sin of a quarter turn should be 1, go 1.0</span></span></code></pre></div><h3 id="os-fspath" tabindex="-1">os.fspath <a class="header-anchor" href="#os-fspath" aria-label="Permalink to os.fspath">​</a></h3><p>从 Python 3.6 开始，有一个神奇的方法表示“转换为文件系统路径”。当给定一个 <code>str</code> 或 <code>bytes</code> 时，它返回输入。</p><p>对于所有类型的对象，它寻找 <code>__fspath__</code> 方法并调用它。这允许传递的对象是“带有元数据的文件名”。</p><p>像 <code>open()</code> 或 <code>stat</code> 这样的普通函数仍然能够使用它们，只要 <code>__fspath__</code> 返回正确的东西。</p><p>例如，这里有一个函数将一些数据写入一个文件，然后检查其大小。它还将文件名记录到标准输出，以便追踪：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def write_and_test(filename):</span></span>
<span class="line"><span>    print(&quot;writing into&quot;, filename)</span></span>
<span class="line"><span>    with open(filename, &quot;w&quot;) as fpout:</span></span>
<span class="line"><span>        fpout.write(&quot;hello&quot;)</span></span>
<span class="line"><span>    print(&quot;size of&quot;, filename, &quot;is&quot;, os.path.getsize(filename))</span></span></code></pre></div><p>你可以用你期望的方式来调用它，用一个字符串作为文件名：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>write_and_test(&quot;plain.txt&quot;)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    writing into plain.txt</span></span>
<span class="line"><span>    size of plain.txt is 5</span></span></code></pre></div><p>然而，可以定义一个新的类，为文件名的字符串表示法添加信息。这样可以使日志记录更加详细，而不改变原来的功能：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>class DocumentedFileName:</span></span>
<span class="line"><span>    def __init__(self, fname, why):</span></span>
<span class="line"><span>        self.fname = fname</span></span>
<span class="line"><span>        self.why = why</span></span>
<span class="line"><span>    def __fspath__(self):</span></span>
<span class="line"><span>        return self.fname</span></span>
<span class="line"><span>    def __repr__(self):</span></span>
<span class="line"><span>        return f&quot;DocumentedFileName(fname={self.fname!r}, why={self.why!r})&quot;</span></span></code></pre></div><p>用 <code>DocumentedFileName</code> 实例作为输入运行该函数，允许 <code>open</code> 和 <code>os.getsize</code> 函数继续工作，同时增强日志：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>write_and_test(DocumentedFileName(&quot;documented.txt&quot;, &quot;because it&#39;s fun&quot;))</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    writing into DocumentedFileName(fname=&#39;documented.txt&#39;, why=&quot;because it&#39;s fun&quot;)</span></span>
<span class="line"><span>    size of DocumentedFileName(fname=&#39;documented.txt&#39;, why=&quot;because it&#39;s fun&quot;) is 5</span></span></code></pre></div><h3 id="欢迎来到-2016-年" tabindex="-1">欢迎来到 2016 年 <a class="header-anchor" href="#欢迎来到-2016-年" aria-label="Permalink to 欢迎来到 2016 年">​</a></h3><p>Python 3.6 是在五年前发布的，但是在这个版本中首次出现的一些特性非常酷，而且没有得到充分利用。如果你还没使用，那么将他们添加到你的工具箱中。</p><hr>`,20)),p("p",null,[s[10]||(s[10]=a("via: ")),e(t,{href:"https://opensource.com/article/21/5/python-36-features"},{default:n(()=>s[9]||(s[9]=[a("https://opensource.com/article/21/5/python-36-features")])),_:1})]),p("p",null,[s[15]||(s[15]=a("作者：")),e(t,{href:"https://opensource.com/users/moshez"},{default:n(()=>s[11]||(s[11]=[a("Moshe Zadka")])),_:1}),s[16]||(s[16]=a(" 选题：")),e(t,{href:"https://github.com/lujun9972"},{default:n(()=>s[12]||(s[12]=[a("lujun9972")])),_:1}),s[17]||(s[17]=a(" 译者：")),e(t,{href:"https://github.com/geekpi"},{default:n(()=>s[13]||(s[13]=[a("geekpi")])),_:1}),s[18]||(s[18]=a(" 校对：")),e(t,{href:"https://github.com/wxy"},{default:n(()=>s[14]||(s[14]=[a("wxy")])),_:1})]),p("p",null,[s[21]||(s[21]=a("本文由 ")),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>s[19]||(s[19]=[a("LCTT")])),_:1}),s[22]||(s[22]=a(" 原创编译，")),e(t,{href:"https://linux.cn/"},{default:n(()=>s[20]||(s[20]=[a("Linux中国")])),_:1}),s[23]||(s[23]=a(" 荣誉推出"))])])}const C=i(h,[["render",r]]);export{k as __pageData,C as default};
